function updatePressureControls(){
 const pressure=map?.pressure.state,available=pressure?.status==='available',control=$('#layerPressure'),notice=$('#pressureStatus'),legend=$('#pressureLegend');
 if(!control||!notice||!legend)return;
 control.disabled=!available;control.checked=available&&pressureEnabled;
 const text=!available?'Hunting pressure is not available for this save.':!pressureEnabled?'Hunting pressure is hidden.':!pressure.hasPressure?(pressure.stale?'No pressure was recorded in the last available save.':'No hunting pressure in this save.'):pressure.stale?'Showing pressure from an earlier save.':'Purple shows hunting pressure from your last save.';
 if(notice.textContent!==text)notice.textContent=text;
 notice.title=available&&pressure.savedAt?'Saved '+date(pressure.savedAt):'';
 legend.hidden=available&&!pressureEnabled;
 legend.className='pressure-key'+(!available?' unavailable':!pressure.hasPressure?' empty':'');
 const label=!available?'Pressure unavailable':!pressure.hasPressure?'No saved pressure':pressure.stale?'Earlier saved pressure':'Hunting pressure';
 const content=available&&pressure.hasPressure?'<i class="pressure-swatch" aria-hidden="true"></i>'+label:label;
 if(legend.innerHTML!==content)legend.innerHTML=content;
 legend.title=notice.title;
}
function refreshPressureLayer(){
 if(view!=='map'||!map?.data||map.data.reserve.id!==reserve||!$('#fieldMap'))return;
 const pressure=state.huntingPressure;
 map.data.huntingPressure=pressure?.reserve===reserve?pressure:null;
 map.pressure.update(map.data.huntingPressure,map.layers.pressure);
 updatePressureControls();
}
function updateZoneList(){const list=$('#zoneList');if(!list)return;const html=zoneList();if(list.innerHTML!==html){const scroll=list.scrollTop,focused=document.activeElement?.closest('[data-action="zone-select"]')?.dataset.id;list.innerHTML=html;list.scrollTop=scroll;if(focused)Array.from(list.querySelectorAll('[data-action="zone-select"]')).find(n=>n.dataset.id===focused)?.focus({preventScroll:true});}$('#zoneListCount').textContent=filteredZones().length+' matching zones';map?.select(selectedZone);}
