 let html;const back=`<div class="detail-navigation">${button('Close','selection-close','','subtle')}${button('Center on map','zone-map','','subtle')}</div>`;
 if(z){html=back+`<div class="eyebrow">${z.source==='save'?'Discovered zone':'Your recorded zone'}</div><h2>${(z.annotation?.name?esc(z.annotation.name):speciesName(z.species,z.speciesKey))}</h2><p class="zone-schedule">${esc(z.need)} · ${hour(z.start)}–${hour(z.end)}</p><div class="big-coordinate">${Math.round(z.x)} / ${Math.round(z.z)}</div><div class="kv"><span>Males</span><strong>${fmt(z.males)}</strong><span>Females</span><strong>${fmt(z.females)}</strong><span>Your plan</span><span>${esc(planLabel(z.annotation?.strategy))}</span></div><p class="muted">Counts update when your game saves.</p>${z.annotation?.notes?'<p>'+esc(z.annotation.notes)+'</p>':''}<div class="detail-actions">${routeButton(z.id)}${button('Edit plan','zone-edit',`data-id="${esc(z.id)}"`)}${button('Animal guide','animal-reference',`data-species="${esc(z.speciesKey||z.species)}"`,'subtle')}</div>`;}
 else if(selectedPoint){html=back+`<div class="eyebrow">${item?.source==='public_map_reference'?'Map reference':item?'Equipment':'Selected location'}</div><h2>${esc(item?.label||'Map point')}</h2><div class="big-coordinate">${Math.round(selectedPoint[0])} / ${Math.round(selectedPoint[1])}</div><p class="muted">${item?.source==='public_map_reference'?'This reference does not indicate whether you have unlocked it. ':''}Markers stay in your companion journal.</p><div class="detail-actions">${button('Save a marker','pin-create','','primary')}${button('Record a zone','zone-create')}</div>`;}
 else html=`<div class="eyebrow">Zone details</div><h2>Choose a zone</h2><p class="muted">Tap a zone to see its herd, schedule and route actions.</p>`;
