function render(){if(!state)return;document.body.dataset.view=view;if(view!=='maps')reserveAtlas.suspend();document.querySelectorAll('nav button').forEach(n=>n.setAttribute('aria-current',n.dataset.view===view?'page':'false'));if(view==='map')return renderMap();map?.destroy();map=null;const renderers={maps:()=>reserveAtlas.render(reserve),overview,recovery,herds,harvests,insights,settings,feedback,reference:()=>referencePanel.render(reserve),career:()=>careerScreen.render(state),studio:()=>shareStudio.render(state),home:()=>fieldLibrary.render('home',reserve),reserves:()=>fieldLibrary.render('reserves',reserve),gear:()=>fieldLibrary.render('gear',reserve),rares:()=>fieldLibrary.render('rares',reserve),faq:()=>fieldLibrary.render('faq',reserve)};const readingPosition=harvestReadingPosition();$('#content').innerHTML=(renderers[view]||overview)();restoreHarvestReadingPosition(readingPosition);if(view==='career')careerScreen.restoreFocus();highlightAnimalPickers();connectionState(connectionReady);if(view==='settings'&&!isPhone)void phoneUI.load();if(view==='feedback'&&!feedbackAttempted)void loadFeedbackInbox();}
