async function act(action,target){
 if(action==='harvest-more'){harvestFilters.limit+=50;updateHarvestFeed();return;}
 if(action==='harvest-reset'){Object.assign(harvestFilters,{query:'',range:'all',limit:50});render();$('#harvestSearch')?.focus();return;}
 if(action==='phone-enable')return openDialog('Connect your phone',`<p>Your phone will be able to see your saved hunts and edit your companion notes through ${esc(phoneUI.info?.serviceHost||'the phone service')}.</p><p>Your PC and companion must stay on. Turn off phone access here to disconnect all paired phones.</p><label class="checkline"><input type="checkbox" name="consent" required><span>Allow private phone access to my companion.</span></label>`,v=>{if(v.consent!=='on')throw Error('Check the box to connect your phone.');return phoneUI.enable();},'Connect phone');
 if(action==='phone-pair')return phoneUI.pair();
 if(action==='phone-disable')return openDialog('Turn off phone access','<p>Your paired phones will stop connecting. Your saved hunts and notes stay on this PC.</p>',()=>phoneUI.disable(),'Turn off');
 if(action==='feedback-read')return markFeedbackRead(target.dataset.id);
 if(action==='feedback-seen')return markGithubFeedbackSeen(target.dataset.id,target.dataset.updated);
 if(action==='feedback-reload'){feedbackAttempted=false;return loadFeedbackInbox();}
 if(action==='animal-reference'){await referencePanel.load();referencePanel.openSpecies(target.dataset.species,reserve);switchView('reference');return;}
 if(action.startsWith('view-'))return switchView(action.slice(5));
 if(action==='shot')return shotDialog();
 if(action==='filters-reset'){Object.assign(filters,filterDefaults);for(const [id,key] of Object.entries({filterSpecies:'species',filterNeed:'need',filterStrategy:'strategy',filterTime:'time',filterSort:'sort',zoneSearch:'search'}))if($('#'+id))$('#'+id).value=filters[key];applyZoneFilters();return;}
 if(action==='workspace-tab')return setWorkspacePanel(target.dataset.panel);
 if(action==='selection-close'){clearZoneSelection();updateZoneList();drawDetail();setWorkspacePanel('map',false);return;}
 if(action==='zone-back'){clearZoneSelection();updateZoneList();drawDetail();setWorkspacePanel('zones',true);return;}
 if(action==='zone-map'){const z=state.zones.find(z=>z.id===selectedZone);if(z)map?.focus(z.x,z.z);else if(selectedPoint)map?.focus(...selectedPoint);setWorkspacePanel('map',true);return;}
 if(action==='zone-select')return chooseZone(target.dataset.id,{focusMap:true});
  if(action==='route-up'||action==='route-down'){const order=[...state.route],i=order.indexOf(target.dataset.id),next=action==='route-up'?i-1:i+1;if(i>=0&&next>=0&&next<order.length){[order[i],order[next]]=[order[next],order[i]];await command({op:'route.reorder',reserve,order,expectedOrder:state.route});await refresh(true);}return;}
 if(action==='evidence')return evidenceDialog(state.encounters.find(e=>e.id===target.dataset.id));
 if(action==='another-shot'){const e=state.encounters.find(e=>e.id===target.dataset.id);await command({op:'encounter.evidence',id:e.id,version:e.version,type:'shot',notes:'Additional shot reported'});return refresh(true);}
 if(action==='search'){const e=state.encounters.find(e=>e.id===target.dataset.id);return openDialog('Search status',`${select('Search activity','search',['searching','paused','abandoned'],e.search)}<p class="small muted">Pausing or abandoning a search does not change the last recorded biological outcome.</p>`,v=>command({op:'encounter.search',id:e.id,version:e.version,...v}));}
 if(action==='zone-create')return zoneDialog();
 if(action==='zone-edit')return zoneDialog(state.zones.find(z=>z.id===target.dataset.id));
 if(action==='route'){const zoneId=target.dataset.id,requestedReserve=reserve,key=reserve+':'+zoneId;if(routePending.has(key))return;const intent=routeIntents.get(key)||{op:'route.toggle',reserve,zoneId,requestId:requestId()};routeIntents.set(key,intent);routePending.add(key);refreshRouteView();try{const result=await command(intent);routeIntents.delete(key);if(reserve===requestedReserve){state.route=result.route;refreshRouteView();}await refresh(true);}finally{setTimeout(()=>{routePending.delete(key);if(reserve===requestedReserve)refreshRouteView();},450);}return;}
 if(action==='zone-view'){const id=target.dataset.id;if(!filteredZones().some(z=>z.id===id)){Object.assign(filters,filterDefaults);rememberFilters();}switchView('map');chooseZone(id,{focusMap:true});return;}
 if(action==='pin-create')return openDialog('Record a field pin',`<div class="form-grid">${select('Pin type','kind',['stand','feeder','tent','outpost','last_seen','shot','scout'],'stand')}${field('Label','label','','text','maxlength="120"')}${field('Map X','x',selectedPoint?.[0]??'','number','required step="any"')}${field('Map Z','z',selectedPoint?.[1]??'','number','required step="any"')}</div>${notes()}`,v=>command({op:'pin.create',reserve,...v}));
 if(action==='session-start')return openDialog('Start a grind session',field('Session name','name','My grind','text','maxlength="120"')+'<p class="small muted">Count saved harvest receipts from this moment, across all reserves. Use the animal filter to focus on your target. Your field notes are linked to this session too.</p>',v=>command({op:'session.start',reserve,...v}),'Start session');
 if(action==='session-end'){await command({op:'session.end'});return refresh(true);}
 if(action==='harvest-link'){const h=target.dataset.id;return openDialog('Link harvest receipt',select('Encounter','encounter',state.encounters.map(e=>[e.id,`${e.species} · ${date(e.createdAt)}`]))+'<p class="small muted">Create an encounter first if the correct animal is not listed. No association is guessed.</p>',v=>{const e=state.encounters.find(e=>e.id===v.encounter);if(!e)throw Error('No encounter is available. Log the animal first.');setTimeout(()=>evidenceDialog(e,h),0);},'Continue');}
 if(action==='spoilers')return openDialog('Population spoiler settings','<div class="callout warning">This can reveal animals you have not discovered. Range matches are experimental candidates, not confirmed Great Ones. Locations are not revealed.</div><label class="checkline"><input type="checkbox" name="consent" required><span>I understand and want to enable population insights.</span></label>',v=>{if(v.consent!=='on')throw Error('Consent is required.');return command({op:'settings',spoilers:true,confirmSpoilers:true});},'Enable insights');
 if(action==='terrain')return openDialog('Enable online terrain','<p>Terrain images are requested from mathartbang.com. No journal or save data is sent. The host receives image requests and your IP address.</p><p class="small muted">The coordinate grid works without this setting. Terrain remains a reference, not proof of an in-game shooting lane.</p>',()=>command({op:'settings',terrain:true}),'Enable terrain');
 if(action==='terrain-retry'){map?.terrain.retry();return;}if(action==='map-expand'){setMapExpanded(!$('#content').classList.contains('native-map-expanded'));return;}if(action==='map-fit')return map.fitVisible();if(action==='zoom-in')return map.zoom(1/1.5);if(action==='zoom-out')return map.zoom(1.5);if(action==='map-home')return map.home();
}
$('#content').addEventListener('click',e=>{const n=e.target.closest('[data-action]');if(n)Promise.resolve(act(n.dataset.action,n)).catch(err=>toast(err.message,true));});
$('#content').addEventListener('input',e=>{if(e.target.id==='zoneSearch'){filters.search=e.target.value;applyZoneFilters();}if(e.target.id==='harvestSearch'){harvestFilters.query=e.target.value;harvestFilters.limit=50;updateHarvestFeed();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['overview','map','recovery','herds','harvests','insights','settings','reference','career','studio','home','reserves','gear','rares','faq','maps','feedback'].includes(next)&&next!==view){setMapExpanded(false);view=next;$('#content').innerHTML='';render();}});
$('#content').addEventListener('change',async e=>{try{const ids={filterSpecies:'species',filterNeed:'need',filterStrategy:'strategy',filterTime:'time',filterSort:'sort'};if(ids[e.target.id]){filters[ids[e.target.id]]=e.target.value;applyZoneFilters();highlightAnimalPickers();}
 if(e.target.id==='harvestRange'){harvestFilters.range=e.target.value;harvestFilters.limit=50;updateHarvestFeed();return;}
 if(e.target.id==='layerPressure'){pressureEnabled=e.target.checked;map.setLayer('pressure',pressureEnabled);updatePressureControls();return;}if(e.target.id==='layerPoi'){map.setLayer('poi',e.target.checked);return;}if(e.target.id==='layerGrid'){map.setLayer('grid',e.target.checked);return;}if(e.target.id==='layerZones'){map.setLayer('zones',e.target.checked);return;}if(e.target.id==='layerEquipment'){map.setLayer('equipment',e.target.checked);return;}
 if(e.target.id==='terrainSetting'){if(e.target.checked){e.target.checked=false;await act('terrain');}else{await command({op:'settings',terrain:false});await refresh(true);}}
 if(e.target.id==='spoilerSetting'){if(e.target.checked){e.target.checked=false;await act('spoilers');}else{await command({op:'settings',spoilers:false});await refresh(true);}}
 }catch(err){toast(err.message,true);}});
document.addEventListener('click',e=>{const b=e.target.closest('nav [data-view]');if(b)switchView(b.dataset.view);});

$('#reserve').onchange=()=>{setMapExpanded(false);reserve=Number($('#reserve').value);requestGeneration++;clearZoneSelection();restoreFilters();workspacePanel='map';const u=new URL(location.href);u.searchParams.set('reserve',reserve);if(/^https?:$/.test(location.protocol))history.replaceState(null,'',u);$('#content').innerHTML='';refresh(true);};
$('#rescan').onclick=async()=>{try{$('#rescan').disabled=true;await command({op:'observer.scan'});await refresh(true);toast('Save check complete.');}catch(e){toast(e.message,true);}finally{$('#rescan').disabled=false;}};
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!$('#modal').open&&state){e.preventDefault();shotDialog();}});
async function refresh(force=false){if(loading){pendingRefresh=true;return;}loading=true;const ticket=requestGeneration,requestedReserve=reserve;try{
 const next=await get(`/api/state?reserve=${requestedReserve}`);if(ticket!==requestGeneration||requestedReserve!==reserve){pendingRefresh=true;return;}state=next;connectionState(true);refreshPressureLayer();
 const picker=$('#reserve');if(!picker.options.length)picker.innerHTML=state.reserves.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');picker.value=String(reserve);
 const badge=$('#connection'),errors=state.observer.sources.filter(s=>s.status==='error').length;
 badge.textContent=!state.observer.connected?'Tracking disconnected':state.observer.error||errors?'Tracking needs attention':'Save tracking on';badge.className='pill '+(!state.observer.connected?'':state.observer.error||errors?'warn':'good');updateHuntStatus();
 const nextSignature=JSON.stringify([reserve,state.zones,state.encounters,state.harvests,state.pins,state.equipment,state.route,state.sessions,state.settings,state.population,state.changes,state.career,state.careerChanges,[state.huntingPressure?.status,state.huntingPressure?.sourceHash,state.huntingPressure?.bounds,state.huntingPressure?.savedAt,state.huntingPressure?.stale],state.observer.error,state.observer.sources.map(s=>[s.name,s.sha,s.status,s.error])]);
 if(view==='harvests'&&$('#harvestFeed')&&!$('#modal').open){if(force||signature!==nextSignature){signature=nextSignature;updateHarvestFeed(true);}}
 else if(!$('#modal').open&&(force||(view!=='studio'&&!(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&$('#content').contains(document.activeElement))))&&(force||signature!==nextSignature||view==='settings')){signature=nextSignature;render();}
 }catch(e){connectionState(false);$('#connection').textContent='Companion disconnected';$('#connection').className='pill warn';if(state&&$('#huntNotice'))$('#huntNotice').innerHTML='<div class="callout warning"><strong>Tracking PC unavailable.</strong> Showing your last loaded data. Reconnecting automatically…</div>';if(!state)$('#content').innerHTML=`<section class="panel"><h1>Companion unavailable</h1><p>${esc(e.message)}</p><p class="muted">Make sure the companion is running on your PC, then try again.</p></section>`;}finally{loading=false;if(pendingRefresh){pendingRefresh=false;queueMicrotask(()=>refresh(true));}}}
try{const boot=await get('/api/bootstrap');token=boot.token;isPhone=boot.phone?.remote===true;reserve=boot.selectedReserve;const valid=['overview','map','recovery','herds','harvests','insights','settings','reference','career','studio','home','reserves','gear','rares','faq','maps','feedback'];const queryReserve=Number(new URL(location.href).searchParams.get('reserve'));if(new URL(location.href).searchParams.has('reserve')&&Number.isInteger(queryReserve)&&queryReserve>=0&&queryReserve<=999)reserve=queryReserve;restoreFilters();view=valid.includes(location.hash.slice(1))?location.hash.slice(1):'map';await refresh(true);setInterval(()=>refresh(),5000);}catch(e){$('#content').innerHTML=`<section class="panel"><h1>Connect to your companion</h1><p>${esc(e.message)}</p></section>`;}

$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-career-reserve]');if(b){reserve=Number(b.dataset.careerReserve);requestGeneration++;refresh(true).then(()=>switchView('map'));}});

$('#content').addEventListener('keydown',e=>{if(e.key==='Escape'){setMapExpanded(false);}});
